#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STACK 64

int main(int argc, char **argv)
{
    long stack[MAX_STACK];
    int top = 0;

    if (argc < 2) {
        puts("ERROR");
        return 0;
    }
    if (argc - 1 > MAX_STACK) {
        puts("ERROR");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long val = strtol(argv[i], &endptr, 10);
        if (endptr != argv[i] && *endptr == '\0') {
            if (top >= MAX_STACK) { puts("ERROR"); return 0; }
            stack[top++] = val;
            continue;
        }
        if (strlen(argv[i]) != 1) { puts("ERROR"); return 0; }
        if (top < 2) { puts("ERROR"); return 0; }
        long b = stack[--top];
        long a = stack[--top];
        long res;
        switch (argv[i][0]) {
            case '+': res = a + b; break;
            case '-': res = a - b; break;
            case '*': res = a * b; break;
            case '/': if (b == 0) { puts("ERROR"); return 0; } res = a / b; break;
            default: puts("ERROR"); return 0;
        }
        if (top >= MAX_STACK) { puts("ERROR"); return 0; }
        stack[top++] = res;
    }
    if (top == 1) {
        printf("%ld\n", stack[0]);
    } else {
        puts("ERROR");
    }
    return 0;
}
